	loaded, ok := testutil.MsgOf[MultiRegistryTagsLoadedMsg](cmd)
	if !ok {
		t.Fatal("the search produced no result message")
	}
	if want := "/v2/api/tags/list"; asked != want {
		t.Errorf("browsed %q, want %q", asked, want)
